import React, {useState} from 'react'
import { useDataLayerValue } from '../DataLayer'
import Contact from './Contact';
import About from './About';
import content from '../content';



function Profile() {

    const [{page},dispatch] = useDataLayerValue();
    const [about,setAbout] = useState(false)
    const [contact,setContact] = useState(false)

    const toggleAbout =  () => {
        setAbout(true);
        setContact(false);
    }

    const toggleContact =  () => {
        setContact(true);
        setAbout(false);
    }

    const mainPage = () => {
        dispatch({
          type: "SET_PAGE",
          page: "main",
        });
      }


    return (
        <div>
            <img className={"absolute mx-4 my-2 w-8 opacity-40 hover:opacity-100"} onClick={mainPage} src={content.back}></img>
            <div className={"w-screen h-screen flex flex-wrap place-content-center"}>

                <div className={"flex flex-wrap"}>
                    <div className={"self-center flex flew-wrap w-36 h-36 bg-yellow-300"} ></div>
                    <div className={"self-center flex flew-wrap w-44 h-44 bg-yellow-400"} ></div>
                    <div onClick={toggleAbout} className={"self-center flex flew-wrap w-52 h-52 bg-yellow-500 z-0 hover:z-30"} >
                        <img className={"object-contain"} src={content.about} ></img>
                    </div>
                    <div className={"self-center flex flew-wrap w-52 h-52 bg-yellow-500"} >
                        <img className={"object-contain transform scale-125"} src={content.keenanColor} ></img>
                    </div>
                    <div onClick={toggleContact} className={"self-center flex flew-wrap w-52 h-52 bg-yellow-600 z-0 hover:z-30"} >
                        <img className={"object-contain"} src={content.about} ></img>
                    </div>
                    <div className={"self-center flex flew-wrap w-44 h-44 bg-yellow-700"} ></div>
                    <div className={"self-center flex flew-wrap w-36 h-36 bg-yellow-800"} ></div>
                </div>



                <div className={`${contact ? "" : "hidden"} mt-10`}>
                    <Contact/>
                </div>
                <div className={`${about ? "" : "hidden"} mt-10`}>
                    <About/>
                </div>


            </div>

        </div>
    )
}

export default Profile
